class Solution {
  public int calculateTime(String keyboard, String word) {
    int[] pos = new int[26];
    for (int i = 0; i < keyboard.length(); i++) pos[keyboard.charAt(i) - 'a'] = i;
    int time = 0, cur = 0;
    for (char c : word.toCharArray()) {
      time += Math.abs(pos[c - 'a'] - cur);
      cur = pos[c - 'a'];
    }
    return time;
  }
}
